CREATE TABLE IF NOT EXISTS kyc_records (admin_account_id TEXT PRIMARY KEY,full_name TEXT NOT NULL,id_type TEXT NOT NULL,id_number TEXT NOT NULL,front_id_url TEXT NOT NULL,back_id_url TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',submitted_at_ms INTEGER NOT NULL,reviewed_at_ms INTEGER,reviewed_by_admin_id TEXT,rejection_reason TEXT,FOREIGN KEY(admin_account_id) REFERENCES auth_accounts(id),FOREIGN KEY(reviewed_by_admin_id) REFERENCES auth_accounts(id));
CREATE INDEX IF NOT EXISTS idx_kyc_status_submitted ON kyc_records(status,submitted_at_ms);
CREATE TABLE IF NOT EXISTS kyc_audit_logs (id TEXT PRIMARY KEY,user_account_id TEXT NOT NULL,admin_account_id TEXT NOT NULL,action TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',timestamp_ms INTEGER NOT NULL,FOREIGN KEY(user_account_id) REFERENCES auth_accounts(id),FOREIGN KEY(admin_account_id) REFERENCES auth_accounts(id));
